};

import React from 'react';
import CLog from '..';
import { Select } from '@arco-design/web-react';

export default () => {
  const getData = (currentPage: number): Promise<{ data: any; total: number }> => {
    const res = {
      data: Array.from({ length: 20 }).map((_, index) => `William Smith_${currentPage}_${index}`),
      total: 60,
    };
    return new Promise(resolve => {
      setTimeout(() => {
        resolve(res);
      }, 1000);
    });
  };

  return (
    <div style={{ width: 600, height: 400 }}>
      <CLog
        title={
          <Select
            options={[
              { label: '实例1', value: '123' },
              { label: '实例2', value: '222' },
            ]}
            style={{ width: 100 }}
          />
        }
        fetcher={getData}
      />
    </div>
  );
};

